// auto-generated.ts — refuse writes/edits to generated files (OMP
// auto-generated-guard, native detector swapped for a zero-dep matcher).
//
// A hand edit to a lockfile or a dist bundle is always wrong: the fix is to
// regenerate from source (npm install / cargo build / tsc). The guard hard-
// errors BEFORE the write with that remediation; bash stays the honest
// override hatch. Setting-gated via `repair.autoGenGuard` (default on).

import { isAbsolute, relative as relPath, resolve as resolvePath } from "node:path";

/** Default generated-file patterns. Suffix/segment match, `**` crosses dirs. */
export const AUTO_GENERATED_PATTERNS: readonly string[] = [
  // Lockfiles — regenerate via the package manager, never hand-edit.
  "package-lock.json",
  "yarn.lock",
  "pnpm-lock.yaml",
  "bun.lock",
  "bun.lockb",
  "Cargo.lock",
  "poetry.lock",
  "composer.lock",
  "Gemfile.lock",
  "flake.lock",
  "Packages.lock.json",
  // Minified bundles
  "*.min.js",
  "*.min.css",
  "*.min.mjs",
  "*.bundle.js",
  // Build outputs (whole directories)
  "dist/**",
  "build/**",
  "out/**",
  "*.egg-info/**",
  "__pycache__/**",
  // Snapshots
  "*.snap",
  "__snapshots__/**",
];

/** Minimal glob match: `*`/`**` = anything (crossing segments — `*.min.js`
 *  must catch a/b/app.min.js), a bare segment matches the path exactly.
 *  Zero-dep — the subagent .worktreeinclude matcher's shape. */
export function matchesPattern(relativePath: string, pattern: string): boolean {
  const p = pattern.replaceAll("\\", "/");
  const f = relativePath.replaceAll("\\", "/").replace(/^\.\//, "");
  if (p === f) return true;
  if (!p.includes("*")) return false; // plain name → equality only (above)
  // Build a regex: * / ** → .* (segment-crossing)
  let re = "^";
  for (let i = 0; i < p.length; i++) {
    const ch = p[i]!;
    if (ch === "*") {
      if (p[i + 1] === "*") i++; // `**` behaves like `*` here
      re += ".*";
    } else {
      re += ch.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
    }
  }
  re += "$";
  return new RegExp(re).test(f);
}

export interface AutoGeneratedMatch {
  pattern: string;
}

/** Match an absolute path against the pattern list. Paths OUTSIDE cwd match
 *  nothing — the guard only knows cwd-relative patterns, and a garbage
 *  `slice(cwd.length+1)` rel path used to spuriously hit `dist/**` and refuse
 *  legit out-of-repo writes. `patterns` injectable for tests. */
export function checkAutoGenerated(
  absPath: string,
  cwd: string,
  patterns: readonly string[] = AUTO_GENERATED_PATTERNS,
): AutoGeneratedMatch | null {
  if (!isAbsolute(absPath)) {
    return matchRel(absPath, patterns);
  }
  const rel = relPath(resolvePath(cwd), resolvePath(absPath));
  if (rel.startsWith("..") || isAbsolute(rel)) return null; // outside cwd — unguarded
  return matchRel(rel, patterns);
}

function matchRel(rel: string, patterns: readonly string[]): AutoGeneratedMatch | null {
  for (const pattern of patterns) {
    if (matchesPattern(rel, pattern)) return { pattern };
  }
  return null;
}

/** The model-facing refusal. Names the pattern + the bash override hatch. */
export function autoGeneratedError(path: string, match: AutoGeneratedMatch): string {
  return (
    `${path} is auto-generated (matched ${match.pattern}) — edit its source and regenerate ` +
    `(npm install / cargo build / tsc …) instead of editing the output. ` +
    `If you really must, use bash to write it deliberately.`
  );
}
